/* =========================================================================
 * 落第骑士英雄谭 · 破军伐刀者智能终端 v1.1.0
 * 运行环境：TavernHelper 卡内脚本（script iframe）；UI 注入 ST 宿主 document
 * 结构：破军战术微光悬浮球(自由吸附) + 桌面浮动可拖拽终端(自由停靠与缩放) + 沙箱 iframe + MVU桥接
 * ========================================================================= */
(async function () {
  'use strict';

  function hostWindow() {
    try { if (window.parent && window.parent !== window && window.parent.document) return window.parent; }
    catch (_) {}
    return window;
  }
  const HW = hostWindow();
  const HD = (function(){ try { return HW.document; } catch (_) { return document; } })();

  const SLOT = '__RK_PHONE_SHELL__';
  try { HW[SLOT] && HW[SLOT].destroy && HW[SLOT].destroy(); } catch (_) {}

  const SS = {
    mode: 'floating', visible: false,
    host: null, iframe: null, blobUrl: null, orb: null, style: null,
    rect: null, orbPos: {x: 0, y: 0},
    disposers: [], booted: false, badge: 0
  };

  const LS = {
    get(k, d) { try { const v = HW.localStorage.getItem(k); return v == null ? d : JSON.parse(v); } catch(_) { return d; } },
    set(k, v) { try { HW.localStorage.setItem(k, JSON.stringify(v)); } catch(_) {} }
  };

  function fn(name) {
    try { if (typeof window[name] === 'function') return window[name]; } catch(_) {}
    try { if (window.TavernHelper && typeof window.TavernHelper[name] === 'function')
      return window.TavernHelper[name].bind(window.TavernHelper); } catch(_) {}
    return null;
  }

  const ORB_W = 44, ORB_H = 44;

  function viewport() {
    const vv = HW.visualViewport;
    let r = vv ? { x: vv.offsetLeft, y: vv.offsetTop, w: vv.width, h: vv.height }
               : { x: 0, y: 0, w: HW.innerWidth, h: HW.innerHeight };
    if (!isFinite(r.w) || !isFinite(r.h) || r.w < 50 || r.h < 50) {
      r = { x: 0, y: 0, w: HW.innerWidth, h: HW.innerHeight };
    }
    return r;
  }

  function preferDrawer() {
    try { return HW.innerWidth <= 768 || HW.matchMedia('(pointer: coarse)').matches; }
    catch(_) { return HW.innerWidth <= 768; }
  }

  function clampRect(r, vp) {
    const GAP = 10, MINW = 320, MINH = 500;
    const w = Math.min(Math.max(r.w, Math.min(MINW, vp.w - GAP * 2)), vp.w - GAP * 2);
    const h = Math.min(Math.max(r.h, Math.min(MINH, vp.h - GAP * 2)), vp.h - GAP * 2);
    return {
      x: Math.min(Math.max(r.x, vp.x + GAP), vp.x + vp.w - w - GAP),
      y: Math.min(Math.max(r.y, vp.y + GAP), vp.y + vp.h - h - GAP),
      w, h
    };
  }

  function clampOrb(x, y) {
    const vp = viewport();
    return {
      x: Math.min(Math.max(x, vp.x + 4), vp.x + vp.w - ORB_W - 4),
      y: Math.min(Math.max(y, vp.y + 4), vp.y + vp.h - ORB_H - 4)
    };
  }

  function fixedBase() {
    try {
      let el = HD.body;
      while (el) {
        const cs = HW.getComputedStyle(el);
        if (cs && (cs.transform !== 'none' || cs.perspective !== 'none' ||
                   (cs.filter && cs.filter !== 'none') ||
                   (cs.willChange && /transform|perspective/.test(cs.willChange)))) {
          const r = el.getBoundingClientRect();
          const sx = el.offsetWidth ? r.width / el.offsetWidth : 1;
          const sy = el.offsetHeight ? r.height / el.offsetHeight : 1;
          return { x: r.left, y: r.top, sx: sx || 1, sy: sy || 1 };
        }
        if (el === HD.documentElement) break;
        el = el.parentElement || HD.documentElement;
      }
    } catch(_) {}
    return { x: 0, y: 0, sx: 1, sy: 1 };
  }

  function writePos(el, vx, vy, vw, vh) {
    const b = fixedBase();
    el.style.left = ((vx - b.x) / b.sx) + 'px';
    el.style.top  = ((vy - b.y) / b.sy) + 'px';
    if (vw != null) el.style.width  = (vw / b.sx) + 'px';
    if (vh != null) el.style.height = (vh / b.sy) + 'px';
  }

  function placeOrb(p) {
    SS.orbPos = p;
    writePos(SS.orb, p.x, p.y);
  }

  function placeOrbTip() {
    const t = SS.orb && SS.orb.querySelector('.tip');
    if (!t || !t.classList.contains('on')) return;
    const vp = viewport();
    const isLeft = (SS.orbPos.x + ORB_W / 2) > (vp.x + vp.w / 2);
    t.classList.toggle('side-l', isLeft);
    t.classList.toggle('side-r', !isLeft);
  }

  function showOrbTip(title, body) {
    const t = SS.orb && SS.orb.querySelector('.tip');
    if (!t) return;
    t.innerHTML = '<b>' + (title || '破军战术终端') + '</b>' + (body ? '<s>' + body + '</s>' : '');
    t.classList.add('on');
    placeOrbTip();
  }

  function clearOrbTip() {
    const t = SS.orb && SS.orb.querySelector('.tip');
    if (t) { t.classList.remove('on'); t.innerHTML = ''; }
  }

  function applyRect(r) {
    writePos(SS.host, r.x, r.y, r.w, r.h);
    SS.rect = r;
  }

  function defaultRect() {
    const vp = viewport();
    const w = Math.min(375, vp.w - 24);
    const h = Math.min(680, vp.h - 24);
    return {
      x: vp.x + Math.round((vp.w - w) / 2),
      y: vp.y + Math.round((vp.h - h) / 2),
      w, h
    };
  }

  function setMode(m) {
    SS.mode = m;
    if (m === 'drawer') {
      SS.host.classList.add('drawer');
      const vp = viewport();
      const w = Math.min(410, vp.w - 16);
      const h = Math.min(vp.h - 24, Math.max(500, Math.round(w * 1.9)));
      writePos(SS.host, vp.x + (vp.w - w) / 2, vp.y + (vp.h - h) / 2, w, h);
    } else {
      SS.host.classList.remove('drawer');
      applyRect(clampRect(LS.get('rk:rect', null) || defaultRect(), viewport()));
    }
  }

  function recenter() {
    const vp = viewport();
    placeOrb(clampOrb(vp.x + vp.w - ORB_W - 16, vp.y + Math.round(vp.h * 0.45)));
    LS.set('rk:orb', { x: SS.orbPos.x, y: SS.orbPos.y });
    const r = defaultRect();
    LS.set('rk:rect', r);
    if (SS.visible && SS.mode === 'floating') applyRect(clampRect(r, vp));
    return true;
  }

  /* 样式注入 */
  const css = `
  #rk-orb {
    position: fixed;
    z-index: 99990;
    width: ${ORB_W}px;
    height: ${ORB_H}px;
    border-radius: 12px;
    background: linear-gradient(145deg, #1c1418 0%, #0d0f14 100%);
    border: 1.5px solid rgba(239, 68, 68, 0.7);
    box-shadow: 0 4px 16px rgba(0,0,0,0.6), 0 0 14px rgba(239, 68, 68, 0.35);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    user-select: none;
    touch-action: none;
    transition: transform 0.12s;
  }
  #rk-orb:hover {
    border-color: #ef4444;
    box-shadow: 0 4px 20px rgba(239, 68, 68, 0.55);
  }
  #rk-orb:active { transform: scale(0.92); }
  #rk-orb .crest {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    line-height: 1;
  }
  #rk-orb .crest b {
    font-size: 13px;
    font-weight: 900;
    color: #ef4444;
    letter-spacing: 0.5px;
    text-shadow: 0 0 6px rgba(239, 68, 68, 0.6);
  }
  #rk-orb .crest span {
    font-size: 7px;
    font-weight: 800;
    color: #fca5a5;
    transform: scale(0.85);
    margin-top: 1px;
  }
  #rk-orb .b {
    position: absolute;
    top: -4px;
    right: -4px;
    min-width: 16px;
    height: 16px;
    border-radius: 8px;
    background: #ef4444;
    color: #fff;
    font: 9px/16px sans-serif;
    font-weight: 800;
    text-align: center;
    padding: 0 4px;
    display: none;
    z-index: 2;
    box-shadow: 0 0 8px rgba(239, 68, 68, 0.8);
  }
  #rk-orb .tip {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 160px;
    padding: 6px 10px;
    border-radius: 10px;
    background: rgba(18, 22, 33, 0.96);
    color: #f8fafc;
    border: 1px solid rgba(239, 68, 68, 0.45);
    box-shadow: 0 8px 24px rgba(0,0,0,0.6);
    font: 11px/1.4 sans-serif;
    display: none;
    pointer-events: none;
    z-index: 3;
  }
  #rk-orb .tip.on { display: block; }
  #rk-orb .tip.side-l { right: calc(100% + 10px); }
  #rk-orb .tip.side-r { left: calc(100% + 10px); }
  #rk-orb .tip b { display: block; font-size: 11.5px; color: #ef4444; font-weight: 700; }
  #rk-orb .tip s { display: block; color: #94a3b8; text-decoration: none; font-size: 10.5px; margin-top: 2px; }

  #rk-shell {
    position: fixed;
    z-index: 99991;
    background: #090c13;
    border: 1.5px solid rgba(239, 68, 68, 0.5);
    border-radius: 20px;
    box-shadow: 0 16px 50px rgba(0, 0, 0, 0.75), 0 0 25px rgba(239, 68, 68, 0.25);
    display: none;
    flex-direction: column;
    overflow: hidden;
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
  }
  #rk-shell.on { display: flex; }
  #rk-shell .bar {
    height: 32px;
    flex: none;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 0 12px;
    cursor: grab;
    user-select: none;
    touch-action: none;
    background: linear-gradient(180deg, #181d2a 0%, #10141f 100%);
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  }
  #rk-shell.busy .bar { cursor: grabbing; }
  #rk-shell .bar .crest-label {
    font-size: 11px;
    font-weight: 800;
    color: #ef4444;
    letter-spacing: 0.5px;
    display: flex;
    align-items: center;
    gap: 5px;
  }
  #rk-shell .bar .bar-handle {
    width: 36px;
    height: 4px;
    border-radius: 2px;
    background: #475569;
    margin: 0 auto;
    opacity: 0.6;
  }
  #rk-shell .bar button {
    width: 26px;
    height: 22px;
    border: 0;
    background: none;
    color: #94a3b8;
    font-size: 13px;
    cursor: pointer;
    border-radius: 5px;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  #rk-shell .bar button:hover { background: rgba(255, 255, 255, 0.1); color: #fff; }
  #rk-shell iframe {
    display: block;
    flex: 1;
    min-height: 0;
    border: 0;
    width: 100%;
    background: #090c13;
  }
  #rk-shell .rsz {
    position: absolute;
    right: 0;
    bottom: 0;
    width: 20px;
    height: 20px;
    cursor: nwse-resize;
    touch-action: none;
  }
  `;

  function buildDom() {
    SS.style = HD.createElement('style');
    SS.style.textContent = css;
    HD.head.appendChild(SS.style);

    SS.orb = HD.createElement('div');
    SS.orb.id = 'rk-orb';
    SS.orb.title = '展开/收起 破军伐刀者战术终端';
    SS.orb.innerHTML = '<div class="crest"><b>破軍</b><span>BLAZER</span></div><span class="b"></span><span class="tip" aria-hidden="true"></span>';
    HD.body.appendChild(SS.orb);

    const op = LS.get('rk:orb', null), vp = viewport();
    const ox = op ? op.x : vp.x + vp.w - ORB_W - 16;
    const oy = op ? op.y : vp.y + Math.round(vp.h * 0.45);
    placeOrb(clampOrb(ox, oy));

    SS.host = HD.createElement('section');
    SS.host.id = 'rk-shell';
    SS.host.setAttribute('role', 'region');
    SS.host.setAttribute('aria-label', '破军战术终端');
    SS.host.innerHTML = `
      <div class="bar">
        <span class="crest-label"><i class="ti ti-shield" style="font-size:14px;"></i> 破軍 TERMINAL</span>
        <div class="bar-handle"></div>
        <button data-a="min" title="收起">—</button>
        <button data-a="x" title="关闭">×</button>
      </div>
      <div class="rsz" aria-hidden="true"></div>
    `;
    HD.body.appendChild(SS.host);
  }

  /* 拖拽与缩放引擎 */
  function bindDrag() {
    const bar = SS.host.querySelector('.bar');
    const rsz = SS.host.querySelector('.rsz');
    let st = null;

    function down(e, kind) {
      if (SS.mode === 'drawer') return;
      if (e.button !== undefined && e.button !== 0) return;
      if (e.target && e.target.tagName === 'BUTTON') return;
      try { e.currentTarget.setPointerCapture && e.currentTarget.setPointerCapture(e.pointerId); } catch(_) {}
      st = { kind, sx: e.clientX, sy: e.clientY, r: { ...SS.rect } };
      SS.host.classList.add('busy');
    }

    function move(e) {
      if (!st) return;
      const dx = e.clientX - st.sx, dy = e.clientY - st.sy, vp = viewport();
      HW.requestAnimationFrame(() => {
        if (!st) return;
        if (st.kind === 'drag') {
          applyRect(clampRect({ ...st.r, x: st.r.x + dx, y: st.r.y + dy }, vp));
        } else {
          applyRect(clampRect({ ...st.r, w: st.r.w + dx, h: st.r.h + dy }, vp));
        }
      });
    }

    function up() {
      if (!st) return;
      st = null;
      SS.host.classList.remove('busy');
      LS.set('rk:rect', SS.rect);
    }

    bar.addEventListener('pointerdown', e => down(e, 'drag'));
    rsz.addEventListener('pointerdown', e => down(e, 'rsz'));
    HD.addEventListener('pointermove', move);
    HD.addEventListener('pointerup', up);
    HD.addEventListener('pointercancel', up);

    SS.disposers.push(() => {
      HD.removeEventListener('pointermove', move);
      HD.removeEventListener('pointerup', up);
      HD.removeEventListener('pointercancel', up);
    });

    /* 悬浮球拖拽与吸边 */
    let ost = null, moved = false;
    SS.orb.addEventListener('pointerdown', e => {
      if (e.cancelable) e.preventDefault();
      e.stopPropagation();
      try { SS.orb.setPointerCapture && SS.orb.setPointerCapture(e.pointerId); } catch(_) {}
      ost = { sx: e.clientX, sy: e.clientY, x: SS.orbPos.x, y: SS.orbPos.y };
      moved = false;
    });

    SS.orb.addEventListener('pointermove', e => {
      if (!ost) return;
      const dx = e.clientX - ost.sx, dy = e.clientY - ost.sy;
      if (!moved && Math.hypot(dx, dy) > 8) moved = true;
      if (moved) placeOrb(clampOrb(ost.x + dx, ost.y + dy));
    });

    SS.orb.addEventListener('pointerup', e => {
      if (e.cancelable) e.preventDefault();
      e.stopPropagation();
      if (!ost) return;
      if (moved) {
        placeOrb(clampOrb(SS.orbPos.x, SS.orbPos.y));
        LS.set('rk:orb', { x: SS.orbPos.x, y: SS.orbPos.y });
      } else {
        clearOrbTip();
        toggle();
      }
      ost = null;
    });

    SS.orb.addEventListener('pointercancel', () => { ost = null; moved = false; });
  }

  function toggle() { SS.visible ? hide() : show(); }

  async function show() {
    clearOrbTip();
    setMode(preferDrawer() ? 'drawer' : 'floating');
    SS.host.classList.add('on');
    SS.visible = true;
    if (!SS.booted) await mountPhone();
  }

  function hide() {
    SS.host.classList.remove('on');
    SS.visible = false;
  }

  /* 内嵌 HTML 解码与沙箱加载 */
  function embeddedPhoneHtml() {
    const b64 = '';
    try {
      return decodeURIComponent(escape(atob(b64)));
    } catch(e) {
      return atob(b64);
    }
  }

  async function mountVia(html, mode) {
    const f = HD.createElement('iframe');
    f.setAttribute('title', '破军战术终端');
    SS.host.appendChild(f);
    SS.iframe = f;
    try {
      await new Promise((res, rej) => {
        const to = setTimeout(() => rej(new Error(mode + ' 超时')), mode === 'blob' ? 3000 : 5000);
        f.onload = () => { clearTimeout(to); res(); };
        if (mode === 'blob') {
          SS.blobUrl = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
          f.src = SS.blobUrl;
        } else {
          f.srcdoc = html;
        }
      });
      const boot = f.contentWindow && f.contentWindow.RKBoot;
      if (typeof boot !== 'function') throw new Error('RKBoot 缺失（' + mode + '）');
      boot(makeBridge());
    } catch(e) {
      try { f.remove(); } catch(_) {}
      if (SS.iframe === f) SS.iframe = null;
      if (mode === 'blob' && SS.blobUrl) { try { HW.URL.revokeObjectURL(SS.blobUrl); } catch(_) {} SS.blobUrl = null; }
      throw e;
    }
  }

  async function mountPhone() {
    if (SS.booted) return;
    const html = embeddedPhoneHtml();
    try {
      await mountVia(html, 'srcdoc');
    } catch(e1) {
      try {
        await mountVia(html, 'blob');
      } catch(e2) {
        console.error('[Hagun-Blazer-Terminal] Mount failed:', e2);
      }
    }
    SS.booted = true;
  }

  /* 桥接对象 (Bridge) */
  function readStat() {
    try {
      if (window.Mvu && Mvu.getMvuData) {
        const d = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
        if (d && d.stat_data) return d.stat_data;
      }
    } catch(_) {}
    try {
      const gv = fn('getVariables');
      const d = gv && gv({ type: 'message', message_id: 'latest' });
      if (d && d.stat_data) return d.stat_data;
    } catch(_) {}
    return null;
  }

  const updateCbs = [];
  function emit(ev) {
    updateCbs.forEach(cb => { try { cb(ev); } catch(_) {} });
  }

  function makeBridge() {
    return {
      getStat: async () => readStat(),
      onUpdate: (cb) => updateCbs.push(cb),
      setOrbBadge: (n) => {
        const b = SS.orb && SS.orb.querySelector('.b');
        if (!b) return;
        SS.badge = n | 0;
        b.textContent = SS.badge > 99 ? '99+' : String(SS.badge);
        b.style.display = SS.badge > 0 ? 'block' : 'none';
      },
      notify: (p) => {
        p = p || {};
        if (!p.title && !p.body) { clearOrbTip(); return; }
        if (SS.visible) return;
        showOrbTip(p.title, p.body);
      },
      ui: {
        close: hide,
        recenter: () => recenter()
      }
    };
  }

  /* 宿主事件监听 */
  function wireEvents() {
    const eon = fn('eventOn');
    if (!eon) return;
    const TE = window.tavern_events || {};
    function safeOn(ev, cb) {
      try { const r = eon(ev, cb); r && r.stop && SS.disposers.push(() => r.stop()); } catch(_) {}
    }

    safeOn(TE.VARIABLE_UPDATE_ENDED || 'mag_variable_update_ended', () => emit({ type: 'vars' }));
    safeOn('mag_variable_update_ended_for_zod', () => emit({ type: 'vars' }));
    safeOn(TE.GENERATION_ENDED || 'generation_ended', () => emit({ type: 'story-turn' }));
    safeOn(TE.CHAT_CHANGED || 'chat_changed', () => emit({ type: 'chat' }));
  }

  function onResize() {
    if (SS.visible) setMode(preferDrawer() ? 'drawer' : 'floating');
    placeOrb(clampOrb(SS.orbPos.x, SS.orbPos.y));
    placeOrbTip();
  }

  function destroy() {
    while (SS.disposers.length) { try { SS.disposers.pop()(); } catch(_) {} }
    try { HW.removeEventListener('resize', onResize); } catch(_) {}
    try { SS.iframe && SS.iframe.remove(); } catch(_) {}
    try { SS.host && SS.host.remove(); } catch(_) {}
    try { SS.orb && SS.orb.remove(); } catch(_) {}
    try { SS.style && SS.style.remove(); } catch(_) {}
    try { SS.blobUrl && HW.URL.revokeObjectURL(SS.blobUrl); } catch(_) {}
    try { delete HW[SLOT]; } catch(_) {}
  }

  buildDom();
  bindDrag();
  wireEvents();

  SS.host.querySelector('[data-a="x"]').onclick = hide;
  SS.host.querySelector('[data-a="min"]').onclick = hide;
  HW.addEventListener('resize', onResize);

  HW[SLOT] = { destroy, show, hide, toggle, recenter };
  try { HW.RKTacticalToggle = toggle; } catch(_) {}

  console.info('[Hagun-Blazer-Terminal] initialized');
})();
